export const PHASES=Object.freeze(["loading","bench","checkin","race","results"]);const r=Object.freeze({loading:Object.freeze({loaded:"bench"}),bench:Object.freeze({race:"checkin"}),checkin:Object.freeze({go:"race",back:"bench"}),race:Object.freeze({finish:"results",skip:"results",back:"checkin"}),results:Object.freeze({again:"race",another:"checkin",back:"checkin",tune:"bench"})});export function nextPhase(e,n){const c=r[e];return c&&c[n]||e}
